-- Baseline schema: the end state of the 36 EF Core migrations that the retired
-- C# backend applied (the last was 20261001045334_DropUnwrittenMarketDataTables).
--
-- Generated by `dotnet ef migrations script` into a throwaway Postgres 16 and
-- read back with `pg_dump --schema-only --no-owner --no-privileges`; the EF
-- history table is left out because app/db_schema/runner.py keeps its own
-- ledger, and a database EF already migrated is adopted rather than re-run.
-- A database built from this file dumps identically to the EF-built one, apart
-- from the four Recency* tables, which are left out (see the next paragraph).
--
-- The four Recency* tables EF also created are not here: ADR 0057 made Python's
-- research schema (app/research/persistence/schema.py) their owner, and it
-- creates them on a database that lacks them. A database EF migrated has them
-- already. The research_* tables create themselves and are not part of this file.

-- Accounts (TABLE)

CREATE TABLE public."Accounts" (
    "Id" uuid NOT NULL,
    "Name" character varying(200) NOT NULL,
    "Type" character varying(20) NOT NULL,
    "BaseCurrency" character varying(10) NOT NULL,
    "InitialCash" numeric(18,8) NOT NULL,
    "Cash" numeric(18,8) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL
);

-- DataLabSessions (TABLE)

CREATE TABLE public."DataLabSessions" (
    "Id" uuid NOT NULL,
    "Name" character varying(300) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "Ticker" character varying(20) NOT NULL,
    "FromDate" character varying(10) NOT NULL,
    "ToDate" character varying(10) NOT NULL,
    "Session" character varying(10) NOT NULL,
    "ForwardFill" boolean NOT NULL,
    "Adjusted" boolean NOT NULL,
    "EntriesJson" jsonb NOT NULL,
    "ChartSnapshotJson" jsonb,
    "CreatedMsUtc" bigint,
    "UpdatedMsUtc" bigint,
    "WindowEndMsUtc" bigint,
    "WindowStartMsUtc" bigint
);

-- DataLakeArtifacts (TABLE)

CREATE TABLE public."DataLakeArtifacts" (
    "Id" bigint NOT NULL,
    "ArtifactKind" character varying(40) NOT NULL,
    "Market" character varying(20),
    "Symbol" character varying(20),
    "TradingDate" date,
    "Resolution" character varying(20),
    "DataType" character varying(20),
    "Provider" character varying(40) NOT NULL,
    "ProviderParams" jsonb NOT NULL,
    "PriceAdjustmentMode" character varying(40),
    "DataContractHash" character(64) NOT NULL,
    "RowCount" integer,
    "FirstBarStartMs" bigint,
    "LastBarStartMs" bigint,
    "CorpActionRevision" character(64),
    "FilePath" text NOT NULL,
    "FileSizeBytes" bigint,
    "FileSha256" character(64),
    "Status" character varying(20) NOT NULL,
    "LeaseOwner" character varying(128),
    "LeaseExpiresAtMs" bigint,
    "AttemptCount" integer DEFAULT 0 NOT NULL,
    "LastError" text,
    "ErrorMessage" text,
    "FetchedAtMs" bigint NOT NULL,
    "CompletedAtMs" bigint,
    "DataRootId" uuid NOT NULL,
    "LeaseGeneration" integer DEFAULT 1 NOT NULL,
    CONSTRAINT ck_artifact_kind_enum CHECK (("ArtifactKind" IN ('time_series_bars', 'factor_file', 'map_file', 'metadata'))),
    CONSTRAINT ck_artifact_kind_fields CHECK ((((("ArtifactKind")::text = 'time_series_bars'::text) AND ("Market" IS NOT NULL) AND ("Symbol" IS NOT NULL) AND ("Resolution" IS NOT NULL) AND ("DataType" IS NOT NULL) AND ("PriceAdjustmentMode" IS NOT NULL) AND (((("Resolution")::text = 'minute'::text) AND ("TradingDate" IS NOT NULL)) OR (("Resolution" IN ('hour', 'daily')) AND ("TradingDate" IS NULL)))) OR (("ArtifactKind" IN ('factor_file', 'map_file')) AND ("Market" IS NOT NULL) AND ("Symbol" IS NOT NULL) AND ("PriceAdjustmentMode" IS NOT NULL) AND ("TradingDate" IS NULL) AND ("Resolution" IS NULL) AND ("DataType" IS NULL)) OR ((("ArtifactKind")::text = 'metadata'::text) AND ("TradingDate" IS NULL) AND ("Resolution" IS NULL) AND ("DataType" IS NULL)))),
    CONSTRAINT ck_data_type_enum CHECK ((("DataType" IS NULL) OR ("DataType" IN ('trade', 'quote')))),
    CONSTRAINT ck_price_adjustment_mode_enum CHECK ((("PriceAdjustmentMode" IS NULL) OR ("PriceAdjustmentMode" IN ('raw', 'polygon_split_adjusted', 'lean_adjusted')))),
    CONSTRAINT ck_resolution_enum CHECK ((("Resolution" IS NULL) OR ("Resolution" IN ('minute', 'hour', 'daily')))),
    CONSTRAINT ck_status_enum CHECK (("Status" IN ('fetching', 'complete', 'stale', 'failed')))
);

-- DataLakeArtifacts_Id_seq (SEQUENCE)

ALTER TABLE public."DataLakeArtifacts" ALTER COLUMN "Id" ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public."DataLakeArtifacts_Id_seq"
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);

