-- clerk_transaction_events (TABLE)

CREATE TABLE public.clerk_transaction_events (
    id bigint NOT NULL,
    event_id character varying(96) NOT NULL,
    transaction_id character varying(96) NOT NULL,
    account_id character varying(64) NOT NULL,
    journal_seq bigint NOT NULL,
    event_kind character varying(64) NOT NULL,
    recorded_at_ms bigint NOT NULL,
    receipt jsonb NOT NULL,
    inserted_at_ms bigint NOT NULL,
    callback_identity character varying(256) DEFAULT ''::character varying NOT NULL,
    lifecycle_state character varying(64) DEFAULT 'submitted'::character varying NOT NULL,
    commission_status character varying(16) DEFAULT 'unknown'::character varying NOT NULL,
    fee double precision,
    broker character varying(16) DEFAULT 'ibkr'::character varying NOT NULL,
    native_order_id character varying(256),
    native_execution_id character varying(256),
    journal_generation character varying(128) DEFAULT ''::character varying NOT NULL,
    CONSTRAINT ck_clerk_transaction_events_journal_seq CHECK ((journal_seq >= 1)),
    CONSTRAINT ck_clerk_transaction_events_recorded_at_ms CHECK ((recorded_at_ms >= 0))
);

-- clerk_transaction_events_id_seq (SEQUENCE)

CREATE SEQUENCE public.clerk_transaction_events_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

-- clerk_transaction_events_id_seq (SEQUENCE OWNED BY)

ALTER SEQUENCE public.clerk_transaction_events_id_seq OWNED BY public.clerk_transaction_events.id;

-- clerk_transaction_feed_status (TABLE)

CREATE TABLE public.clerk_transaction_feed_status (
    account_id character varying(64) NOT NULL,
    state character varying(32) NOT NULL,
    headline character varying(128) NOT NULL,
    detail character varying(512) NOT NULL,
    updated_at_ms bigint NOT NULL,
    high_water_journal_seq bigint,
    lag_records bigint,
    lag_is_lower_bound boolean DEFAULT false NOT NULL,
    CONSTRAINT ck_clerk_transaction_feed_status_high_water CHECK (((high_water_journal_seq IS NULL) OR (high_water_journal_seq >= 0))),
    CONSTRAINT ck_clerk_transaction_feed_status_lag CHECK (((lag_records IS NULL) OR (lag_records >= 0))),
    CONSTRAINT ck_clerk_transaction_feed_status_updated_at_ms CHECK ((updated_at_ms >= 0))
);

-- clerk_transaction_projection_cursors (TABLE)

CREATE TABLE public.clerk_transaction_projection_cursors (
    account_id character varying(64) NOT NULL,
    journal_path text NOT NULL,
    last_byte_offset bigint NOT NULL,
    last_journal_seq bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    journal_generation character varying(128) DEFAULT ''::character varying NOT NULL,
    CONSTRAINT ck_clerk_transaction_projection_cursors_byte_offset CHECK ((last_byte_offset >= 0)),
    CONSTRAINT ck_clerk_transaction_projection_cursors_journal_seq CHECK ((last_journal_seq >= 0))
);

-- clerk_transactions (TABLE)

CREATE TABLE public.clerk_transactions (
    id bigint NOT NULL,
    transaction_id character varying(96) NOT NULL,
    account_id character varying(64) NOT NULL,
    journal_seq bigint NOT NULL,
    recorded_at_ms bigint NOT NULL,
    transaction_kind character varying(64) NOT NULL,
    strategy_instance_id character varying(128) NOT NULL,
    run_id character varying(128) NOT NULL,
    intent_id character varying(256) NOT NULL,
    order_ref character varying(512) NOT NULL,
    order_id bigint,
    perm_id bigint,
    exec_id character varying(256),
    receipt jsonb NOT NULL,
    inserted_at_ms bigint NOT NULL,
    updated_at_ms bigint NOT NULL,
    lifecycle_state character varying(64) DEFAULT 'submitted'::character varying NOT NULL,
    commission_status character varying(16) DEFAULT 'unknown'::character varying NOT NULL,
    fee double precision,
    broker character varying(16) DEFAULT 'ibkr'::character varying NOT NULL,
    native_order_id character varying(256),
    native_execution_id character varying(256),
    journal_generation character varying(128) DEFAULT ''::character varying NOT NULL,
    transaction_origin character varying(32) DEFAULT 'manual'::character varying NOT NULL,
    order_instruction jsonb DEFAULT '{}'::jsonb NOT NULL,
    CONSTRAINT ck_clerk_transactions_journal_seq CHECK ((journal_seq >= 1)),
    CONSTRAINT ck_clerk_transactions_origin CHECK ((transaction_origin IN ('manual', 'strategy', 'recovery', 'emergency', 'shutdown', 'force_flat', 'other'))),
    CONSTRAINT ck_clerk_transactions_recorded_at_ms CHECK ((recorded_at_ms >= 0))
);

-- clerk_transactions_id_seq (SEQUENCE)

CREATE SEQUENCE public.clerk_transactions_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

-- clerk_transactions_id_seq (SEQUENCE OWNED BY)

ALTER SEQUENCE public.clerk_transactions_id_seq OWNED BY public.clerk_transactions.id;

