ALTER TABLE ONLY public.clerk_transaction_events ALTER COLUMN id SET DEFAULT nextval('public.clerk_transaction_events_id_seq'::regclass);

-- clerk_transactions id (DEFAULT)

ALTER TABLE ONLY public.clerk_transactions ALTER COLUMN id SET DEFAULT nextval('public.clerk_transactions_id_seq'::regclass);

