-- ix_data_lake_artifacts_corp_action_lookup (INDEX)

CREATE INDEX ix_data_lake_artifacts_corp_action_lookup ON public."DataLakeArtifacts" USING btree ("Symbol", "ArtifactKind") WHERE ("ArtifactKind" IN ('factor_file', 'map_file'));

