-- uq_data_lake_artifacts_aggregated_bars (INDEX)

CREATE UNIQUE INDEX uq_data_lake_artifacts_aggregated_bars ON public."DataLakeArtifacts" USING btree ("DataRootId", "Market", "Symbol", "Resolution", "DataType", "Provider", "PriceAdjustmentMode") WHERE ((("ArtifactKind")::text = 'time_series_bars'::text) AND (("Resolution")::text = ANY (ARRAY[('hour'::character varying)::text, ('daily'::character varying)::text])));

-- uq_data_lake_artifacts_corp_actions (INDEX)

CREATE UNIQUE INDEX uq_data_lake_artifacts_corp_actions ON public."DataLakeArtifacts" USING btree ("DataRootId", "Market", "Symbol", "ArtifactKind", "Provider", "PriceAdjustmentMode") WHERE (("ArtifactKind")::text = ANY (ARRAY[('factor_file'::character varying)::text, ('map_file'::character varying)::text]));

-- uq_data_lake_artifacts_metadata (INDEX)

CREATE UNIQUE INDEX uq_data_lake_artifacts_metadata ON public."DataLakeArtifacts" USING btree ("DataRootId", "DataContractHash") WHERE (("ArtifactKind")::text = 'metadata'::text);

-- uq_data_lake_artifacts_minute_bars (INDEX)

CREATE UNIQUE INDEX uq_data_lake_artifacts_minute_bars ON public."DataLakeArtifacts" USING btree ("DataRootId", "Market", "Symbol", "TradingDate", "DataType", "Provider", "PriceAdjustmentMode") WHERE ((("ArtifactKind")::text = 'time_series_bars'::text) AND (("Resolution")::text = 'minute'::text));

